/**
 * BodyOutline — the dashed silhouette the patient lines up inside during
 * the guided photo session, one natural human outline per pose (front /
 * side / back), drawn as smooth cubic-Bézier paths with no straight
 * segments. Front and back are generated by mirroring a right-half point
 * list so the figures stay perfectly symmetric; the side profile (facing
 * left, arm hanging in front of the torso) is hand-authored. All three
 * read as people, not placards.
 */
import React from 'react';
import { StyleSheet, View } from 'react-native';
import Svg, { Path } from 'react-native-svg';
import type { GuidedAngle } from '@/lib/guided-photos';

const OUTLINE_IDLE = 'rgba(255, 255, 255, 0.85)';
const OUTLINE_READY = '#7FD8A4';

/** ViewBox width — mirroring reflects x across W/2. */
const W = 120;

type Pt = readonly [number, number];

interface Seg {
  c1: Pt;
  c2: Pt;
  to: Pt;
}

function seg(c1: Pt, c2: Pt, to: Pt): Seg {
  return { c1, c2, to };
}

function fmt(n: number): string {
  return Number.isInteger(n) ? String(n) : n.toFixed(1);
}

/**
 * Closed, left/right-symmetric path from a right-half segment list running
 * top-center → down the right side → bottom-center; the left half is the
 * same walk mirrored back up, so both sides always match exactly.
 */
function mirrored(start: Pt, segs: readonly Seg[]): string {
  const parts: string[] = [`M ${fmt(start[0])} ${fmt(start[1])}`];
  for (const s of segs) {
    parts.push(
      `C ${fmt(s.c1[0])} ${fmt(s.c1[1])} ${fmt(s.c2[0])} ${fmt(s.c2[1])} ${fmt(s.to[0])} ${fmt(s.to[1])}`,
    );
  }
  for (let i = segs.length - 1; i >= 0; i--) {
    const from = i === 0 ? start : segs[i - 1].to;
    const s = segs[i];
    parts.push(
      `C ${fmt(W - s.c2[0])} ${fmt(s.c2[1])} ${fmt(W - s.c1[0])} ${fmt(s.c1[1])} ${fmt(W - from[0])} ${fmt(from[1])}`,
    );
  }
  return `${parts.join(' ')} Z`;
}

/**
 * Front pose: relaxed A-stance — head, neck, shoulders, arms slightly away
 * from the body with a notch of daylight at the armpit, feet about hip
 * width apart, toes angled a touch outward.
 */
const FRONT_RIGHT: readonly Seg[] = [
  seg([70, 10], [77, 18], [77, 30]), // crown → right side of head
  seg([77, 39], [74, 46], [69, 51]), // jaw
  seg([68, 54], [69, 57], [73, 59]), // neck
  seg([83, 62], [91, 66], [94, 74]), // trapezius → shoulder
  seg([97, 82], [99, 95], [100, 108]), // upper arm, slightly out
  seg([101, 121], [103, 133], [103, 143]), // forearm
  seg([103, 152], [101, 157], [97, 159]), // hand, outer edge
  seg([93, 161], [91, 156], [91, 149]), // around the fingertips
  seg([91, 138], [90, 126], [88, 115]), // inner forearm, back up
  seg([86, 104], [84, 94], [81, 88]), // inner upper arm → armpit
  seg([79, 100], [78, 114], [78, 127]), // torso side → waist
  seg([78, 141], [85, 151], [88, 163]), // hip
  seg([90, 175], [90, 184], [89, 193]), // outer thigh
  seg([87, 207], [86, 217], [85, 227]), // knee
  seg([84, 243], [82, 255], [81, 264]), // shin → ankle
  seg([81, 272], [83, 277], [87, 280]), // ankle → toe, angled out
  seg([90, 283], [89, 287], [84, 287]), // around the toes
  seg([77, 287], [72, 287], [71, 283]), // sole → heel
  seg([70, 278], [70, 271], [70, 264]), // inner ankle
  seg([71, 250], [71, 239], [72, 229]), // inner calf
  seg([72, 216], [70, 205], [68, 198]), // inner knee → thigh
  seg([65, 192], [63, 189], [60, 188]), // up to the crotch
];

/**
 * Back pose: same build seen from behind — arms hanging closer to the
 * body, fuller through the glutes, feet a touch closer together.
 */
const BACK_RIGHT: readonly Seg[] = [
  seg([70, 10], [76, 18], [76, 30]), // crown → side of head
  seg([76, 38], [73, 45], [69, 50]), // skull base
  seg([68, 53], [69, 56], [72, 58]), // nape
  seg([82, 60], [92, 64], [95, 72]), // shoulder, a little squarer
  seg([97, 80], [97, 92], [96, 104]), // upper arm, close to the body
  seg([95, 117], [95, 129], [94, 139]), // forearm
  seg([94, 149], [93, 155], [89, 157]), // hand, outer edge
  seg([85, 159], [84, 154], [84, 147]), // around the fingertips
  seg([84, 136], [84, 124], [83, 113]), // inner forearm
  seg([82, 102], [81, 93], [79, 87]), // armpit
  seg([78, 99], [77, 113], [77, 126]), // torso side → waist
  seg([77, 140], [84, 150], [86, 162]), // hip / glute
  seg([88, 174], [88, 183], [87, 192]), // outer thigh
  seg([85, 206], [84, 216], [83, 226]), // knee
  seg([82, 242], [80, 254], [79, 263]), // calf → ankle
  seg([79, 271], [80, 277], [83, 280]), // ankle → toe
  seg([86, 283], [85, 287], [80, 287]), // around the toes
  seg([74, 287], [70, 287], [69, 283]), // sole → heel
  seg([68, 278], [68, 271], [68, 264]), // inner ankle
  seg([69, 250], [69, 240], [70, 230]), // inner calf
  seg([70, 216], [68, 205], [66, 198]), // inner thigh
  seg([64, 193], [62, 190], [60, 189]), // up to the crotch
];

/** Side profile, facing left: one body path plus the near arm in front. */
const SIDE_BODY =
  'M 58 11 C 68 12 74 20 74 30 C 74 38 71 44 68 49 C 67 53 68 56 71 58 ' +
  'C 79 61 85 66 87 74 C 90 86 91 98 90 110 C 89 124 87 132 86 140 ' +
  'C 89 148 91 158 90 168 C 89 180 87 188 85 196 C 83 210 82 220 82 228 ' +
  'C 83 240 82 252 80 262 C 79 271 79 277 81 281 C 82 285 79 287 74 287 ' +
  'C 62 288 50 288 43 286 C 39 284 39 280 42 278 C 46 274 50 269 51 262 ' +
  'C 53 248 54 238 55 228 C 56 216 56 208 55 198 C 54 186 52 176 50 166 ' +
  'C 48 156 47 148 47 140 C 46 128 45 118 46 108 C 47 96 48 88 50 78 ' +
  'C 52 70 52 64 51 60 C 50 57 47 55 45 52 C 42 49 41 45 41 41 ' +
  'C 40 38 40 35 42 33 C 43 29 44 26 46 22 C 49 15 53 11 58 11 Z';

const SIDE_ARM =
  'M 62 74 C 66 80 67 90 66 100 C 65 112 63 122 61 132 ' +
  'C 59 142 57 150 55 156 C 53 162 49 162 48 157 C 47 152 49 146 51 138 ' +
  'C 53 128 55 118 55 106 C 55 94 56 82 58 74 C 59 71 61 71 62 74 Z';

/**
 * The silhouette paths per pose — exported so the verification suite can
 * assert every outline stays a smooth all-Bézier figure.
 */
export const OUTLINE_PATHS: Record<GuidedAngle, readonly string[]> = {
  front: [mirrored([60, 10], FRONT_RIGHT)],
  side: [SIDE_BODY, SIDE_ARM],
  back: [mirrored([60, 10], BACK_RIGHT)],
};

interface BodyOutlineProps {
  angle: GuidedAngle;
  ready: boolean;
  /** Fades the outline behind the countdown numeral. */
  dim?: boolean;
}

export function BodyOutline({ angle, ready, dim = false }: BodyOutlineProps) {
  const stroke = ready ? OUTLINE_READY : OUTLINE_IDLE;
  const fill = ready ? 'rgba(127, 216, 164, 0.10)' : 'rgba(255, 255, 255, 0.04)';
  return (
    <View
      pointerEvents="none"
      style={[styles.outlineWrap, dim && styles.outlineDim]}
      testID="guided-outline"
    >
      <View style={styles.outlineBox}>
        <Svg width="100%" height="100%" viewBox={`0 0 ${W} 300`}>
          {OUTLINE_PATHS[angle].map((d, index) => (
            <Path
              key={index}
              d={d}
              stroke={stroke}
              strokeWidth={3.5}
              strokeDasharray="10 8"
              strokeLinejoin="round"
              strokeLinecap="round"
              fill={index === 0 ? fill : 'none'}
            />
          ))}
        </Svg>
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  outlineWrap: {
    ...StyleSheet.absoluteFill,
    alignItems: 'center',
    justifyContent: 'center',
  },
  outlineDim: {
    opacity: 0.4,
  },
  outlineBox: {
    height: '75%',
    aspectRatio: 120 / 300,
  },
});
